package com.feynman.backend;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.context.properties.ConfigurationPropertiesScan;

/**
 * Entry point for the Feynman learning-platform backend.
 *
 * <p>The backend evaluates a user's notebooks/pages and scores how well the
 * topic appears to be understood, following the Feynman technique (if you can
 * explain it simply, you understand it). Scores replace the front-end's
 * hard-coded {@code progress.ts} placeholder values.</p>
 */
@SpringBootApplication
@ConfigurationPropertiesScan
public class FeynmanBackendApplication {

    public static void main(String[] args) {
        SpringApplication.run(FeynmanBackendApplication.class, args);
    }
}

package com.feynman.backend.controller;

import com.feynman.backend.service.OpenAiEvaluationService.EvaluationException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * Translates uncaught exceptions into RFC 7807 {@link ProblemDetail} responses.
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ProblemDetail handleValidation(MethodArgumentNotValidException ex) {
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.BAD_REQUEST);
        pd.setTitle("Invalid request");
        pd.setDetail(ex.getBindingResult().getAllErrors().stream()
                .findFirst()
                .map(err -> err.getDefaultMessage())
                .orElse("Validation failed"));
        return pd;
    }

    @ExceptionHandler(EvaluationException.class)
    public ProblemDetail handleEvaluation(EvaluationException ex) {
        log.error("Evaluation failed", ex);
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.BAD_GATEWAY);
        pd.setTitle("Evaluation failed");
        pd.setDetail(ex.getMessage());
        return pd;
    }

    @ExceptionHandler(Exception.class)
    public ProblemDetail handleGeneric(Exception ex) {
        log.error("Unexpected error", ex);
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.INTERNAL_SERVER_ERROR);
        pd.setTitle("Internal error");
        pd.setDetail("An unexpected error occurred.");
        return pd;
    }
}

package com.feynman.backend.dto;

import jakarta.validation.constraints.NotNull;

import java.util.List;

/**
 * Request payload for {@code POST /api/evaluate}.
 *
 * <p>The frontend sends its full set of notebooks and pages; the backend
 * returns an understanding score (0–100) for every page and an aggregate
 * score for every notebook. When {@code notebookId} is provided, only that
 * notebook (and its pages) is evaluated.</p>
 *
 * @param notebookId Optional filter — evaluate only this notebook when set.
 */
public record EvaluateRequest(
        @NotNull List<NotebookDto> notebooks,
        @NotNull List<PageDto> pages,
        String notebookId
) {
}

package com.feynman.backend.dto;

import java.util.Map;

/**
 * Response payload for {@code POST /api/evaluate}.
 *
 * <p>Scores are split so the frontend can merge page- and notebook-level
 * results independently, matching the shape consumed by {@code setLiveScores}.
 * Each map is keyed by the entity id (matching the frontend seed ids).</p>
 */
public record EvaluationResponse(
        Map<String, ScoreDto> pageScores,
        Map<String, ScoreDto> notebookScores
) {
}

package com.feynman.backend.dto;

/**
 * Mirrors the frontend {@code Notebook} type.
 */
public record NotebookDto(
        String id,
        String title,
        String color
) {
}

package com.feynman.backend.dto;

import java.util.List;

/**
 * Mirrors the frontend {@code Page} type. Represents a single page whose
 * understanding we want to score.
 */
public record PageDto(
        String id,
        String notebookId,
        String parentId,
        String title,
        String content,
        List<TextBoxDto> boxes,
        Integer order
) {
    /** Combined free text of the page (content + all text boxes). */
    public String combinedText() {
        StringBuilder sb = new StringBuilder();
        if (content != null) {
            sb.append(content);
        }
        if (boxes != null) {
            for (TextBoxDto box : boxes) {
                if (box != null && box.text() != null && !box.text().isBlank()) {
                    sb.append("\n").append(box.text());
                }
            }
        }
        return sb.toString().trim();
    }
}

package com.feynman.backend.dto;

/**
 * A single understanding score for a notebook or page.
 *
 * @param score              Understanding percentage, 0–100.
 * @param understandingNotes Short human-readable explanation of the score.
 */
public record ScoreDto(
        int score,
        String understandingNotes
) {
}

package com.feynman.backend.dto;

/**
 * Mirrors the frontend {@code TextBox} type: a free-floating text box on the
 * page canvas. Only {@code text} matters for evaluation.
 */
public record TextBoxDto(
        String id,
        Double x,
        Double y,
        String text,
        Double width
) {
}

import type { Notebook, Page } from '@/types'
import { evaluateNotes } from '@/services/evaluationApi'
import type { EvaluationResult } from '@/services/evaluationApi'

/**
 * @deprecated Use `@/services/evaluationApi` directly.
 *
 * Kept as a thin re-export so any existing imports of `@/api/evaluation`
 * continue to resolve to the single canonical client.
 */
export type { Score, EvaluationResult } from '@/services/evaluationApi'
export { evaluateNotes } from '@/services/evaluationApi'

/** @deprecated Prefer `evaluateNotes(notebooks, pages, notebookId?)`. */
export async function evaluateNotebooks(payload: {
  notebooks: Notebook[]
  pages: Page[]
  notebookId?: string
}): Promise<EvaluationResult> {
  return evaluateNotes(payload.notebooks, payload.pages, payload.notebookId)
}

import { describe, it, expect, beforeEach, vi } from 'vitest'
import { mount } from '@vue/test-utils'
import { nextTick } from 'vue'
import FormatMenu from '@/components/FormatMenu.vue'

// jsdom implements neither execCommand nor queryCommandState, so we stub them
// and assert against the spies. queryCommandState defaults to false unless a
// test overrides it (used for the active-state assertions below).
let execCommand: ReturnType<typeof vi.fn>
let queryCommandState: ReturnType<typeof vi.fn>

beforeEach(() => {
  execCommand = vi.fn().mockReturnValue(true)
  queryCommandState = vi.fn().mockReturnValue(false)
  // @ts-expect-error - not present in jsdom's Document typings
  document.execCommand = execCommand
  // @ts-expect-error - not present in jsdom's Document typings
  document.queryCommandState = queryCommandState
})

const props = { x: 100, y: 100 }

describe('FormatMenu', () => {
  describe('accessibility roles', () => {
    it('exposes a menu role with an accessible label', () => {
      const wrapper = mount(FormatMenu, { props })
      const menu = wrapper.get('[role="menu"]')
      expect(menu.attributes('aria-label')).toBe('Text formatting')
    })

    it('labels the inline-formatting group', () => {
      const wrapper = mount(FormatMenu, { props })
      const group = wrapper.get('[aria-label="Inline formatting"]')
      expect(group.attributes('role')).toBe('group')
    })

    it('marks list items with the menuitem role', () => {
      const wrapper = mount(FormatMenu, { props })
      expect(wrapper.findAll('[role="menuitem"]').length).toBeGreaterThan(0)
    })
  })

  describe('formatting commands', () => {
    it('runs the bold command and emits "applied" when Bold is clicked', async () => {
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[aria-label="Bold"]').trigger('click')
      expect(execCommand).toHaveBeenCalledWith('bold', false, undefined)
      expect(wrapper.emitted('applied')).toBeTruthy()
    })

    it('forces CSS styling for colour commands', async () => {
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[aria-label="No text colour"]').trigger('click')
      expect(execCommand).toHaveBeenCalledWith('styleWithCSS', false, 'true')
      expect(execCommand).toHaveBeenCalledWith('foreColor', false, '#242424')
    })

    it('applies a highlight colour via hiliteColor', async () => {
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[aria-label="No highlight"]').trigger('click')
      expect(execCommand).toHaveBeenCalledWith('hiliteColor', false, 'transparent')
    })

    it('prompts for and normalises a link URL', async () => {
      const promptSpy = vi.spyOn(window, 'prompt').mockReturnValue('example.com')
      const wrapper = mount(FormatMenu, { props })
      await wrapper.get('[title="Insert link (Ctrl+K)"]').trigger('click')
      expect(promptSpy).toHaveBeenCalled()
      expect(execCommand).toHaveBeenCalledWith('createLink', false, 'https://example.com')
    })
  })

  describe('active-state indicators', () => {
    it('reflects the current selection state via aria-pressed and .active', async () => {
      queryCommandState.mockImplementation((cmd: string) => cmd === 'bold')
      const wrapper = mount(FormatMenu, { props })
      await nextTick()
      const bold = wrapper.get('[aria-label="Bold"]')
      expect(bold.attributes('aria-pressed')).toBe('true')
      expect(bold.classes()).toContain('active')

      const italic = wrapper.get('[aria-label="Italic"]')
      expect(italic.attributes('aria-pressed')).toBe('false')
      expect(italic.classes()).not.toContain('active')
    })
  })

  describe('keyboard shortcuts', () => {
    it('runs bold on Ctrl+B', () => {
      mount(FormatMenu, { props, attachTo: document.body })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'b', ctrlKey: true }))
      expect(execCommand).toHaveBeenCalledWith('bold', false, undefined)
    })

    it('runs strikethrough only with the Shift modifier on Ctrl+Shift+X', () => {
      mount(FormatMenu, { props, attachTo: document.body })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'x', ctrlKey: true }))
      expect(execCommand).not.toHaveBeenCalledWith('strikeThrough', false, undefined)

      window.dispatchEvent(
        new KeyboardEvent('keydown', { key: 'x', ctrlKey: true, shiftKey: true })
      )
      expect(execCommand).toHaveBeenCalledWith('strikeThrough', false, undefined)
    })

    it('emits "close" on Escape', () => {
      const wrapper = mount(FormatMenu, { props })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape' }))
      expect(wrapper.emitted('close')).toBeTruthy()
    })

    it('ignores shortcut keys without a modifier', () => {
      mount(FormatMenu, { props })
      window.dispatchEvent(new KeyboardEvent('keydown', { key: 'b' }))
      expect(execCommand).not.toHaveBeenCalledWith('bold', false, undefined)
    })
  })

  describe('selection preservation', () => {
    it('prevents default on mousedown so the selection is not stolen', async () => {
      const wrapper = mount(FormatMenu, { props })
      const event = new MouseEvent('mousedown', { cancelable: true, bubbles: true })
      wrapper.get('[role="menu"]').element.dispatchEvent(event)
      expect(event.defaultPrevented).toBe(true)
    })
  })

  describe('lifecycle', () => {
    it('stops listening for selection changes after unmount', async () => {
      const removeSpy = vi.spyOn(document, 'removeEventListener')
      const wrapper = mount(FormatMenu, { props })
      await nextTick()
      wrapper.unmount()
      expect(removeSpy).toHaveBeenCalledWith('selectionchange', expect.any(Function))
    })
  })
})

import { describe, it, expect } from 'vitest'
import { mount } from '@vue/test-utils'
import TextBoxItem from '@/components/TextBoxItem.vue'

describe('TextBoxItem', () => {
  const baseProps = {
    offsetXInPixels: 40,
    offsetYInPixels: 120,
    text: 'Hello'
  }

  it('renders at the given position', () => {
    const wrapper = mount(TextBoxItem, {
      props: { ...baseProps, widthInPixels: 200 }
    })
    const style = wrapper.get('.box-wrap').attributes('style') ?? ''
    expect(style).toContain('left: 40px')
    expect(style).toContain('top: 120px')
    expect(style).toContain('width: 200px')
  })

  it('renders drafts directly in edit mode (textarea) with a placeholder', () => {
    const draft = mount(TextBoxItem, { props: { ...baseProps, isDraft: true } })
    const textarea = draft.get('textarea')
    expect(textarea.attributes('placeholder')).toBe('Type here…')
    expect(textarea.classes()).toContain('is-draft')
    expect(draft.find('.drag-handle').exists()).toBe(false)
  })

  it('renders saved boxes in display mode (no textarea until clicked)', async () => {
    const wrapper = mount(TextBoxItem, { props: baseProps })
    expect(wrapper.find('textarea').exists()).toBe(false)
    expect(wrapper.get('.text-display').text()).toBe('Hello')

    await wrapper.get('.text-display').trigger('click')
    expect(wrapper.find('textarea').exists()).toBe(true)
  })

  it('renders a drag handle for saved boxes and emits drag-start on mousedown', async () => {
    const wrapper = mount(TextBoxItem, { props: baseProps })
    const handle = wrapper.get('.drag-handle')
    await handle.trigger('mousedown')
    expect(wrapper.emitted('drag-start')).toHaveLength(1)
    expect(wrapper.emitted('drag-start')![0][0]).toBeInstanceOf(MouseEvent)
  })

  it('emits update:text on input while editing', async () => {
    const wrapper = mount(TextBoxItem, { props: baseProps })
    await wrapper.get('.text-display').trigger('click')
    const textarea = wrapper.get('textarea')
    await textarea.setValue('Changed')
    expect(wrapper.emitted('update:text')).toBeTruthy()
    expect(wrapper.emitted('update:text')!.at(-1)).toEqual(['Changed'])
  })

  it('emits blur when the textarea blurs', async () => {
    const wrapper = mount(TextBoxItem, { props: { ...baseProps, isDraft: true } })
    await wrapper.get('textarea').trigger('blur')
    expect(wrapper.emitted('blur')).toHaveLength(1)
  })

  it('focuses the textarea on mount when focusOnMount is set', () => {
    const wrapper = mount(TextBoxItem, {
      props: { ...baseProps, isDraft: true, focusOnMount: true },
      attachTo: document.body
    })
    expect(document.activeElement).toBe(wrapper.get('textarea').element)
    wrapper.unmount()
  })

  describe('inline references', () => {
    const refProps = {
      offsetXInPixels: 0,
      offsetYInPixels: 0,
      text: 'See Napoleon here',
      references: [{ id: 'ref-1', start: 4, end: 12, targetPageId: 'pg-napoleon' }]
    }

    it('renders linked ranges as .ref-link and plain text around them', () => {
      const wrapper = mount(TextBoxItem, { props: refProps })
      const link = wrapper.get('.ref-link')
      expect(link.text()).toBe('Napoleon')
      expect(wrapper.get('.text-display').text()).toBe('See Napoleon here')
    })

    it('emits ref-click with the target page id when a link is clicked', async () => {
      const wrapper = mount(TextBoxItem, { props: refProps })
      await wrapper.get('.ref-link').trigger('click')
      expect(wrapper.emitted('ref-click')).toBeTruthy()
      expect(wrapper.emitted('ref-click')![0]).toEqual(['pg-napoleon'])
    })

    it('emits ref-hover with the target and a rect on mouseenter', async () => {
      const wrapper = mount(TextBoxItem, { props: refProps })
      await wrapper.get('.ref-link').trigger('mouseenter')
      const payload = wrapper.emitted('ref-hover')![0][0] as {
        targetPageId: string
        rect: DOMRect
      }
      expect(payload.targetPageId).toBe('pg-napoleon')
      expect(payload.rect).toBeDefined()
    })

    it('emits request-link-menu on right-click of a link', async () => {
      const wrapper = mount(TextBoxItem, { props: refProps })
      await wrapper.get('.ref-link').trigger('contextmenu')
      const payload = wrapper.emitted('request-link-menu')![0][0] as {
        referenceId: string
      }
      expect(payload.referenceId).toBe('ref-1')
    })

    it('does not enter edit mode when a link is clicked', async () => {
      const wrapper = mount(TextBoxItem, { props: refProps })
      await wrapper.get('.ref-link').trigger('click')
      expect(wrapper.find('textarea').exists()).toBe(false)
    })
  })

  describe('create-link request', () => {
    it('emits request-link with the current selection offsets on contextmenu', async () => {
      const wrapper = mount(TextBoxItem, {
        props: { ...baseProps, text: 'See Napoleon here' },
        attachTo: document.body
      })
      // Enter edit mode to expose the textarea.
      await wrapper.get('.text-display').trigger('click')
      const textarea = wrapper.get('textarea')
      const el = textarea.element as HTMLTextAreaElement
      el.setSelectionRange(4, 12) // "Napoleon"

      await textarea.trigger('contextmenu')

      const payload = wrapper.emitted('request-link')![0][0] as {
        start: number
        end: number
      }
      expect(payload.start).toBe(4)
      expect(payload.end).toBe(12)
      wrapper.unmount()
    })

    it('does not emit request-link when there is no selection', async () => {
      const wrapper = mount(TextBoxItem, {
        props: { ...baseProps, text: 'Hello' },
        attachTo: document.body
      })
      await wrapper.get('.text-display').trigger('click')
      const textarea = wrapper.get('textarea')
      ;(textarea.element as HTMLTextAreaElement).setSelectionRange(3, 3)

      await textarea.trigger('contextmenu')

      expect(wrapper.emitted('request-link')).toBeFalsy()
      wrapper.unmount()
    })
  })
})

import { describe, it, expect } from 'vitest'
import { mount } from '@vue/test-utils'
import TextBoxItem from '@/components/TextBoxItem.vue'

describe('TextBoxItem', () => {
  const baseProps = {
    offsetXInPixels: 40,
    offsetYInPixels: 120,
    text: 'Hello'
  }

  it('renders at the given position', () => {
    const wrapper = mount(TextBoxItem, {
      props: { ...baseProps, widthInPixels: 200 }
    })
    const style = wrapper.get('.box-wrap').attributes('style') ?? ''
    expect(style).toContain('left: 40px')
    expect(style).toContain('top: 120px')
    expect(style).toContain('width: 200px')
  })

  it('renders the (sanitized) prop HTML into the editable', () => {
    const wrapper = mount(TextBoxItem, {
      props: { ...baseProps, text: '<b>Bold</b> text' }
    })
    expect(wrapper.get('.text-box').element.innerHTML).toContain('<b>Bold</b>')
  })

  it('exposes a contenteditable textbox', () => {
    const wrapper = mount(TextBoxItem, { props: baseProps })
    const box = wrapper.get('.text-box')
    expect(box.attributes('contenteditable')).toBe('true')
    expect(box.attributes('role')).toBe('textbox')
  })

  describe('draft mode', () => {
    it('marks drafts with the is-draft class and a placeholder', () => {
      const draft = mount(TextBoxItem, {
        props: { ...baseProps, text: '', isDraft: true }
      })
      const box = draft.get('.text-box')
      expect(box.classes()).toContain('is-draft')
      expect(box.attributes('data-placeholder')).toBe('Type here…')
    })

    it('hides the drag handle for drafts', () => {
      const draft = mount(TextBoxItem, { props: { ...baseProps, isDraft: true } })
      expect(draft.find('.drag-handle').exists()).toBe(false)
    })

    it('shows a drag handle for saved boxes', () => {
      const wrapper = mount(TextBoxItem, { props: baseProps })
      expect(wrapper.find('.drag-handle').exists()).toBe(true)
    })
  })

  describe('events', () => {
    it('emits drag-start on drag-handle mousedown', async () => {
      const wrapper = mount(TextBoxItem, { props: baseProps })
      await wrapper.get('.drag-handle').trigger('mousedown')
      expect(wrapper.emitted('drag-start')).toHaveLength(1)
      expect(wrapper.emitted('drag-start')![0][0]).toBeInstanceOf(MouseEvent)
    })

    it('emits update:text with sanitized HTML on input', async () => {
      const wrapper = mount(TextBoxItem, { props: baseProps })
      const box = wrapper.get('.text-box')
      box.element.innerHTML = 'Changed'
      await box.trigger('input')
      expect(wrapper.emitted('update:text')).toBeTruthy()
      expect(wrapper.emitted('update:text')!.at(-1)).toEqual(['Changed'])
    })

    it('emits blur when the editable blurs', async () => {
      const wrapper = mount(TextBoxItem, { props: baseProps })
      await wrapper.get('.text-box').trigger('blur')
      expect(wrapper.emitted('blur')).toHaveLength(1)
    })

    it('emits request-format with the event on contextmenu', async () => {
      const wrapper = mount(TextBoxItem, { props: baseProps })
      await wrapper.get('.text-box').trigger('contextmenu')
      expect(wrapper.emitted('request-format')).toHaveLength(1)
      expect(wrapper.emitted('request-format')![0][0]).toBeInstanceOf(MouseEvent)
    })
  })

  describe('checkboxes', () => {
    it('mirrors a toggled checkbox onto the checked attribute and re-emits', async () => {
      const wrapper = mount(TextBoxItem, {
        props: {
          ...baseProps,
          text: '<span class="tick" contenteditable="false"><input type="checkbox"></span> task'
        }
      })
      const checkbox = wrapper.get('input[type="checkbox"]')
      const el = checkbox.element as HTMLInputElement
      el.checked = true
      await checkbox.trigger('change')

      expect(el.hasAttribute('checked')).toBe(true)
      const emitted = wrapper.emitted('update:text')
      expect(emitted).toBeTruthy()
      expect(emitted!.at(-1)![0] as string).toContain('checked')
    })
  })

  describe('focus behaviour', () => {
    it('focuses the editable on mount when focusOnMount is set', () => {
      const wrapper = mount(TextBoxItem, {
        props: { ...baseProps, text: '', isDraft: true, focusOnMount: true },
        attachTo: document.body
      })
      expect(document.activeElement).toBe(wrapper.get('.text-box').element)
      wrapper.unmount()
    })

    it('exposes a focus() method', () => {
      const wrapper = mount(TextBoxItem, {
        props: baseProps,
        attachTo: document.body
      })
      ;(wrapper.vm as unknown as { focus: () => void }).focus()
      expect(document.activeElement).toBe(wrapper.get('.text-box').element)
      wrapper.unmount()
    })
  })
})

import type { Notebook, Page } from '@/types'

/**
 * Client for the Feynman backend evaluation API.
 *
 * The base URL is configurable via `VITE_API_BASE_URL`; by default it is empty
 * so requests hit the Vite dev proxy (`/api → http://localhost:8080`).
 */
const API_BASE_URL = import.meta.env.VITE_API_BASE_URL ?? ''

/** A single understanding score returned by the backend. */
export interface Score {
  score: number
  understandingNotes: string
}

/** Response shape of {@code POST /api/evaluate}. */
export interface EvaluationResult {
  /** Page id → score. */
  pageScores: Record<string, Score>
  /** Notebook id → aggregate score. */
  notebookScores: Record<string, Score>
}

/**
 * Ask the backend to grade how well the user understands each topic.
 *
 * @param notebooks  All notebooks (or the subset to evaluate).
 * @param pages      All pages (the backend filters by `notebookId` if given).
 * @param notebookId Optional — evaluate only this notebook and its pages.
 */
export async function evaluateNotes(
  notebooks: Notebook[],
  pages: Page[],
  notebookId?: string
): Promise<EvaluationResult> {
  const res = await fetch(`${API_BASE_URL}/api/evaluate`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ notebooks, pages, notebookId })
  })

  if (!res.ok) {
    throw new Error(`Evaluation request failed: ${res.status} ${res.statusText}`)
  }

  return (await res.json()) as EvaluationResult
}

import { defineStore } from 'pinia'
import type { Notebook, NotebookTree, Page, PageNode, TextBox, TextReference } from '@/types'
import { seedNotebooks, seedPages } from '@/data/seed'

const STORAGE_KEY = 'onenote-notes:v2'
/** Separate key for lightweight UI preferences (progress toggle, etc.). */
const UI_STORAGE_KEY = 'onenote-ui:v1'

interface PersistShape {
  notebooks: Notebook[]
  pages: Page[]
}

/** Ensure every page has a boxes[] array (older persisted data may lack it). */
function normalizePages(pages: Page[]): Page[] {
  return pages.map((p) => ({
    ...p,
    boxes: Array.isArray(p.boxes)
      ? p.boxes.map((b) => ({
          ...b,
          references: Array.isArray(b.references) ? b.references : []
        }))
      : []
  }))
}

/** Load persisted UI preferences (best-effort). */
function loadShowProgress(): boolean {
  try {
    const raw = localStorage.getItem(UI_STORAGE_KEY)
    if (raw) {
      const parsed = JSON.parse(raw) as { showProgress?: boolean }
      return parsed.showProgress === true
    }
  } catch {
    /* ignore malformed storage */
  }
  return false
}

function loadState(): PersistShape {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (raw) {
      const parsed = JSON.parse(raw) as PersistShape
      if (Array.isArray(parsed.notebooks) && Array.isArray(parsed.pages)) {
        return { notebooks: parsed.notebooks, pages: normalizePages(parsed.pages) }
      }
    }
  } catch {
    /* ignore malformed storage */
  }
  // Fallback to fresh seed data (deep-cloned so we never mutate the source).
  return {
    notebooks: structuredClone(seedNotebooks),
    pages: normalizePages(structuredClone(seedPages))
  }
}

function uid(prefix: string): string {
  return `${prefix}-${Math.random().toString(36).slice(2, 9)}`
}

interface State {
  notebooks: Notebook[]
  pages: Page[]
  /** Global toggle: show completion progress badges across all sidebars. */
  showProgress: boolean
}

export const useNotesStore = defineStore('notes', {
  state: (): State => {
    const { notebooks, pages } = loadState()
    return { notebooks, pages, showProgress: loadShowProgress() }
  },

  getters: {
    /** Pages belonging to a notebook. */
    pagesByNotebook: (state) => {
      return (notebookId: string): Page[] =>
        state.pages.filter((p) => p.notebookId === notebookId)
    },

    /** Look up a single page by id. */
    pageById: (state) => {
      return (pageId: string): Page | undefined =>
        state.pages.find((p) => p.id === pageId)
    },

    /** Look up a single notebook by id. */
    notebookById: (state) => {
      return (notebookId: string): Notebook | undefined =>
        state.notebooks.find((n) => n.id === notebookId)
    },

    /**
     * Build the nested page tree for a notebook from the flat `parentId` list.
     */
    pageTree: (state) => {
      return (notebookId: string): PageNode[] => {
        const nodes = new Map<string, PageNode>()
        const notebookPages = state.pages.filter((p) => p.notebookId === notebookId)

        for (const p of notebookPages) {
          nodes.set(p.id, { ...p, children: [] })
        }

        const roots: PageNode[] = []
        for (const node of nodes.values()) {
          if (node.parentId && nodes.has(node.parentId)) {
            nodes.get(node.parentId)!.children.push(node)
          } else {
            roots.push(node)
          }
        }

        const sortRec = (list: PageNode[]) => {
          list.sort((a, b) => a.order - b.order)
          list.forEach((n) => sortRec(n.children))
        }
        sortRec(roots)

        return roots
      }
    },

    /**
     * Human-readable breadcrumb for a page: notebook title followed by every
     * ancestor page title and finally the page itself. Used for link tooltips.
     */
    pagePath(): (pageId: string) => string[] {
      return (pageId: string): string[] => {
        const page = this.pages.find((p) => p.id === pageId)
        if (!page) return []
        const titles: string[] = []
        let cursor: Page | undefined = page
        while (cursor) {
          titles.unshift(cursor.title || 'Untitled')
          cursor = cursor.parentId
            ? this.pages.find((p) => p.id === cursor!.parentId)
            : undefined
        }
        const notebook = this.notebooks.find((n) => n.id === page.notebookId)
        if (notebook) titles.unshift(notebook.title)
        return titles
      }
    },

    /** Every notebook paired with its resolved page tree (for the ref picker). */
    allNotebookTrees(): NotebookTree[] {
      return this.notebooks.map((notebook) => ({
        notebook,
        tree: this.pageTree(notebook.id)
      }))
    }
  },

  actions: {
    persist() {
      try {
        localStorage.setItem(
          STORAGE_KEY,
          JSON.stringify({ notebooks: this.notebooks, pages: this.pages })
        )
      } catch {
        /* storage might be unavailable — non-fatal */
      }
    },

    // --- UI preferences ------------------------------------------------------
    /** Toggle (or explicitly set) the global progress display. */
    setShowProgress(value?: boolean) {
      this.showProgress = value ?? !this.showProgress
      try {
        localStorage.setItem(
          UI_STORAGE_KEY,
          JSON.stringify({ showProgress: this.showProgress })
        )
      } catch {
        /* storage might be unavailable — non-fatal */
      }
    },

    // --- Notebook CRUD -------------------------------------------------------
    addNotebook(title = 'New Notebook', color = '#7719aa'): Notebook {
      const notebook: Notebook = { id: uid('nb'), title, color }
      this.notebooks.push(notebook)
      this.persist()
      return notebook
    },

    renameNotebook(id: string, title: string) {
      const nb = this.notebooks.find((n) => n.id === id)
      if (nb) {
        nb.title = title
        this.persist()
      }
    },

    deleteNotebook(id: string) {
      this.notebooks = this.notebooks.filter((n) => n.id !== id)
      this.pages = this.pages.filter((p) => p.notebookId !== id)
      this.persist()
    },

    // --- Page CRUD -----------------------------------------------------------
    addPage(notebookId: string, parentId: string | null = null, title = 'Untitled Page'): Page {
      const siblings = this.pages.filter(
        (p) => p.notebookId === notebookId && p.parentId === parentId
      )
      const order = siblings.length
        ? Math.max(...siblings.map((s) => s.order)) + 1
        : 0
      const page: Page = {
        id: uid('pg'),
        notebookId,
        parentId,
        title,
        content: '',
        boxes: [],
        order
      }
      this.pages.push(page)
      this.persist()
      return page
    },

    updatePage(id: string, patch: Partial<Pick<Page, 'title' | 'content'>>) {
      const page = this.pages.find((p) => p.id === id)
      if (page) {
        Object.assign(page, patch)
        this.persist()
      }
    },

    // --- Text box CRUD -------------------------------------------------------
    /** Persist a new (non-empty) text box onto a page. */
    addTextBox(pageId: string, box: Omit<TextBox, 'id'>): TextBox | undefined {
      const page = this.pages.find((p) => p.id === pageId)
      if (!page) return
      if (!page.boxes) page.boxes = []
      const tb: TextBox = {
        id: uid('tb'),
        references: [],
        ...box,
        text: sanitizeBoxHtml(box.text ?? '')
      }
      page.boxes.push(tb)
      this.persist()
      return tb
    },

    updateTextBox(
      pageId: string,
      boxId: string,
      patch: Partial<Pick<TextBox, 'text' | 'x' | 'y' | 'width'>>
    ) {
      const page = this.pages.find((p) => p.id === pageId)
      const box = page?.boxes?.find((b) => b.id === boxId)
      if (box) {
        // Sanitize incoming rich-text before it is stored/persisted.
        const cleanPatch =
          patch.text !== undefined
            ? { ...patch, text: sanitizeBoxHtml(patch.text) }
            : patch
        // When the text changes, drop any inline reference whose linked
        // substring no longer matches its recorded offsets (best-effort sync).
        if (
          cleanPatch.text !== undefined &&
          cleanPatch.text !== box.text &&
          box.references?.length
        ) {
          const oldText = box.text
          const newText = cleanPatch.text
          box.references = box.references.filter((ref) => {
            const oldSub = oldText.slice(ref.start, ref.end)
            return newText.slice(ref.start, ref.end) === oldSub
          })
        }
        Object.assign(box, cleanPatch)
        this.persist()
      }
    },

    /**
     * Add an inline page reference to a box. Optionally replaces the marked
     * range with `linkText` first (the modal lets the user edit the wording),
     * then records the reference over the resulting range.
     */
    addBoxReference(
      pageId: string,
      boxId: string,
      params: { start: number; end: number; targetPageId: string; linkText?: string }
    ): TextReference | undefined {
      const page = this.pages.find((p) => p.id === pageId)
      const box = page?.boxes?.find((b) => b.id === boxId)
      if (!box) return
      if (!box.references) box.references = []

      let { start, end } = params
      // Apply an (optional) text replacement for the linked range.
      if (params.linkText !== undefined && params.linkText !== box.text.slice(start, end)) {
        const before = box.text.slice(0, start)
        const after = box.text.slice(end)
        const newEnd = start + params.linkText.length
        // Shift any existing references that sit after the edited range.
        const delta = params.linkText.length - (end - start)
        box.references = box.references
          .filter((ref) => ref.end <= start || ref.start >= end) // drop overlaps
          .map((ref) =>
            ref.start >= end
              ? { ...ref, start: ref.start + delta, end: ref.end + delta }
              : ref
          )
        box.text = before + params.linkText + after
        end = newEnd
      }

      const reference: TextReference = {
        id: uid('ref'),
        start,
        end,
        targetPageId: params.targetPageId
      }
      // Replace any reference that overlaps the new range, then add.
      box.references = box.references.filter(
        (ref) => ref.end <= start || ref.start >= end
      )
      box.references.push(reference)
      box.references.sort((a, b) => a.start - b.start)
      this.persist()
      return reference
    },

    /** Remove a single inline reference from a box. */
    removeBoxReference(pageId: string, boxId: string, referenceId: string) {
      const page = this.pages.find((p) => p.id === pageId)
      const box = page?.boxes?.find((b) => b.id === boxId)
      if (box?.references) {
        box.references = box.references.filter((r) => r.id !== referenceId)
        this.persist()
      }
    },

    /**
     * Update an existing inline reference: optionally rewrite its linked text
     * (adjusting its own end offset and shifting later references) and/or point
     * it at a different page.
     */
    updateBoxReference(
      pageId: string,
      boxId: string,
      referenceId: string,
      patch: { linkText?: string; targetPageId?: string }
    ) {
      const page = this.pages.find((p) => p.id === pageId)
      const box = page?.boxes?.find((b) => b.id === boxId)
      const ref = box?.references?.find((r) => r.id === referenceId)
      if (!box || !ref) return

      // Rewrite the linked substring if the text changed.
      if (patch.linkText !== undefined && patch.linkText !== box.text.slice(ref.start, ref.end)) {
        const before = box.text.slice(0, ref.start)
        const after = box.text.slice(ref.end)
        const delta = patch.linkText.length - (ref.end - ref.start)
        box.text = before + patch.linkText + after
        // Shift references that sit entirely after the edited range.
        for (const other of box.references!) {
          if (other.id !== ref.id && other.start >= ref.end) {
            other.start += delta
            other.end += delta
          }
        }
        ref.end = ref.start + patch.linkText.length
      }

      if (patch.targetPageId !== undefined) {
        ref.targetPageId = patch.targetPageId
      }

      box.references!.sort((a, b) => a.start - b.start)
      this.persist()
    },

    /** Remove a text box (used when it is emptied out). */
    removeTextBox(pageId: string, boxId: string) {
      const page = this.pages.find((p) => p.id === pageId)
      if (page?.boxes) {
        page.boxes = page.boxes.filter((b) => b.id !== boxId)
        this.persist()
      }
    },

    /** Delete a page and all of its descendants. */
    deletePage(id: string) {
      const toRemove = new Set<string>([id])
      let changed = true
      while (changed) {
        changed = false
        for (const p of this.pages) {
          if (p.parentId && toRemove.has(p.parentId) && !toRemove.has(p.id)) {
            toRemove.add(p.id)
            changed = true
          }
        }
      }
      this.pages = this.pages.filter((p) => !toRemove.has(p.id))
      this.persist()
    },

    /** Re-parent a page (e.g. drag & drop). Guards against cycles. */
    movePage(id: string, newParentId: string | null) {
      if (id === newParentId) return
      // Prevent moving a page under one of its own descendants.
      let cursor = newParentId
      while (cursor) {
        if (cursor === id) return
        cursor = this.pages.find((p) => p.id === cursor)?.parentId ?? null
      }
      const page = this.pages.find((p) => p.id === id)
      if (page) {
        page.parentId = newParentId
        this.persist()
      }
    },

    resetToSeed() {
      this.notebooks = structuredClone(seedNotebooks)
      this.pages = normalizePages(structuredClone(seedPages))
      this.persist()
    }
  }
})

import { defineStore } from 'pinia'
import type { Notebook, NotebookTree, Page, PageNode, TextBox, TextReference } from '@/types'
import { seedNotebooks, seedPages } from '@/data/seed'
import { sanitizeBoxHtml } from '@/utils/sanitizeHtml'

const STORAGE_KEY = 'onenote-notes:v2'
/** Separate key for lightweight UI preferences (progress toggle, etc.). */
const UI_STORAGE_KEY = 'onenote-ui:v1'

interface PersistShape {
  notebooks: Notebook[]
  pages: Page[]
}

/** Ensure every page has a boxes[] array (older persisted data may lack it). */
function normalizePages(pages: Page[]): Page[] {
  return pages.map((p) => ({
    ...p,
    boxes: Array.isArray(p.boxes)
      ? p.boxes.map((b) => ({
          ...b,
          references: Array.isArray(b.references) ? b.references : []
        }))
      : []
  }))
}

/** Load persisted UI preferences (best-effort). */
function loadShowProgress(): boolean {
  try {
    const raw = localStorage.getItem(UI_STORAGE_KEY)
    if (raw) {
      const parsed = JSON.parse(raw) as { showProgress?: boolean }
      return parsed.showProgress === true
    }
  } catch {
    /* ignore malformed storage */
  }
  return false
}

function loadState(): PersistShape {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (raw) {
      const parsed = JSON.parse(raw) as PersistShape
      if (Array.isArray(parsed.notebooks) && Array.isArray(parsed.pages)) {
        return { notebooks: parsed.notebooks, pages: normalizePages(parsed.pages) }
      }
    }
  } catch {
    /* ignore malformed storage */
  }
  // Fallback to fresh seed data (deep-cloned so we never mutate the source).
  return {
    notebooks: structuredClone(seedNotebooks),
    pages: normalizePages(structuredClone(seedPages))
  }
}

function uid(prefix: string): string {
  return `${prefix}-${Math.random().toString(36).slice(2, 9)}`
}

interface State {
  notebooks: Notebook[]
  pages: Page[]
  /** Global toggle: show completion progress badges across all sidebars. */
  showProgress: boolean
}

export const useNotesStore = defineStore('notes', {
  state: (): State => {
    const { notebooks, pages } = loadState()
    return { notebooks, pages, showProgress: loadShowProgress() }
  },

  getters: {
